VL("k23");
M("Khóa lưỡng phân phân biệt chim và dơi nên dùng cặp đặc điểm",["có lông vũ / có lông mao","biết bay / không biết bay","màu đen / màu nâu","ăn sâu / ăn quả"],1);
V("Để xây dựng khóa lưỡng phân cho 4 loài cây trong vườn trường, bước đầu tiên là",["quan sát, liệt kê đặc điểm từng loài để tìm cặp đặc điểm đối lập","đặt tên tùy ý","nhổ hết cây","chọn màu đẹp"],1);

VL("k24");
M("Vì sao kháng sinh không có tác dụng chữa bệnh do virus?",["Vì kháng sinh diệt vi khuẩn, virus không có cấu tạo tế bào nên không bị ảnh hưởng","Vì virus quá to","Vì kháng sinh quá yếu","Vì virus không gây bệnh"],1);
V("Mùa dịch cúm, việc nào giúp em phòng bệnh hiệu quả?",["Rửa tay thường xuyên, đeo khẩu trang nơi đông người, tiêm phòng","Dùng chung khăn mặt","Tự uống kháng sinh","Không ngủ đủ giấc"],1);
T("Về virus và đời sống:",["+Virus được dùng để sản xuất một số loại vắc-xin.","+Virus có thể gây bệnh cho cả thực vật, động vật.","-Virus có thể sinh sản độc lập ngoài tế bào.","+Bệnh khảm thuốc lá do virus gây ra."],1);

VL("k25");
M("Vì sao làm dưa muối, cà muối thì dưa cà chua và để được lâu?",["Vì vi khuẩn lactic lên men tạo axit, ức chế vi khuẩn gây hỏng","Vì muối làm dưa ngọt","Vì nắng chiếu","Vì không có vi khuẩn"],1);
V("Vì sao bác sĩ khuyên không tự ý dùng kháng sinh khi chưa có chỉ định?",["Vì dùng sai gây kháng kháng sinh, thuốc mất tác dụng","Vì kháng sinh rất ngon","Vì kháng sinh chữa mọi bệnh","Vì kháng sinh không có tác dụng phụ"],1);
T("Vai trò của vi khuẩn:",["+Vi khuẩn cố định đạm giúp cây họ đậu có nhiều đạm.","+Vi khuẩn trong ruột giúp tiêu hóa thức ăn.","-Vi khuẩn chỉ sống trong cơ thể người.","+Vi khuẩn gây bệnh có thể lây qua thức ăn, nước uống."],1);

VL("k26");
M("Vì sao sữa chua để trong tủ lạnh thì lâu chua hơn để ngoài?",["Vì nhiệt độ thấp làm vi khuẩn lactic hoạt động chậm lại","Vì tủ lạnh giết hết vi khuẩn","Vì tủ lạnh làm sữa ngọt","Vì tủ lạnh có ánh sáng"],1);
V("Làm sữa chua mà ủ ở nơi quá lạnh, sữa không đông lại. Nguyên nhân là",["vi khuẩn lactic không hoạt động được ở nhiệt độ thấp","cho quá nhiều sữa","sữa quá ngọt","dùng cốc thủy tinh"],1);

VL("k27");
M("Vì sao bệnh sốt rét thường phổ biến ở vùng rừng núi nhiệt đới?",["Vì khí hậu nóng ẩm, nhiều muỗi Anopheles truyền bệnh","Vì khí hậu lạnh","Vì ít muỗi","Vì không có nước"],1);
V("Tảo trong biển có vai trò quan trọng vì",["quang hợp tạo oxygen và là thức ăn cho nhiều sinh vật biển","gây bệnh cho người","làm nước biển ngọt","không có vai trò"],1);

VL("k28");
M("Vì sao nấm mốc thường mọc trên bánh mì để lâu ở nơi ẩm?",["Vì bào tử nấm có trong không khí phát triển trong điều kiện ẩm, giàu chất hữu cơ","Vì bánh mì tự tạo nấm","Vì nắng chiếu","Vì bánh mì quá khô"],1);
V("Bạn em bị nấm da do mặc quần áo ẩm. Lời khuyên phù hợp là",["giữ da khô thoáng, phơi quần áo dưới nắng, đi khám bác sĩ","mặc quần áo ẩm tiếp","dùng chung khăn","tự bôi thuốc bất kì"],1);
T("Về vai trò của nấm:",["+Nấm phân hủy xác sinh vật, làm sạch môi trường.","+Một số nấm dùng để sản xuất thuốc kháng sinh (penicillin).","-Mọi loại nấm đều có hại.","+Nấm độc có thể gây tử vong nếu ăn phải."],1);

VL("k29");
M("Vì sao cây hạt kín là nhóm thực vật phổ biến và đa dạng nhất?",["Vì có hoa, quả bảo vệ hạt, thích nghi với nhiều môi trường","Vì không có rễ","Vì sinh sản bằng bào tử","Vì sống dưới nước"],1);
V("Vì sao vùng đồi trọc dễ bị xói mòn và lũ quét?",["Vì không có thực vật che phủ, giữ đất và nước","Vì có quá nhiều cây","Vì đất quá cứng","Vì không có mưa"],1);
T("Phân biệt các nhóm thực vật:",["+Rêu sống ở nơi ẩm ướt, chưa có rễ chính thức.","+Dương xỉ có mạch dẫn, sinh sản bằng bào tử.","-Cây hạt trần có hoa và quả thật.","+Cây lúa, cây cam thuộc nhóm Hạt kín."],1);

VL("k30");
M("Một cây có lá kim, hạt nằm lộ trên các vảy của nón. Cây thuộc nhóm",["Hạt trần","Hạt kín","Dương xỉ","Rêu"],1);
V("Khi lập bảng phân loại các cây trong vườn trường, cách trình bày khoa học nhất là",["bảng gồm tên cây, đặc điểm nhận biết, nhóm phân loại","viết đoạn văn dài","chỉ ghi tên cây","vẽ tranh không ghi chú"],1);

VL("k31");
M("Vì sao dơi được xếp vào lớp Thú dù biết bay?",["Vì dơi đẻ con và nuôi con bằng sữa","Vì dơi có lông vũ","Vì dơi đẻ trứng","Vì dơi sống về đêm"],1);
V("Muỗi, ruồi là động vật có hại. Biện pháp hạn chế chúng hiệu quả là",["vệ sinh nhà cửa, không để nước đọng, xử lí rác","nuôi thêm muỗi","để rác khắp nơi","mở cửa suốt đêm không màn"],1);
T("Đặc điểm các nhóm động vật có xương sống:",["+Cá hô hấp bằng mang.","+Chim có lông vũ, đẻ trứng.","-Bò sát thở bằng mang.","+Ếch có giai đoạn nòng nọc sống dưới nước."],1);

VL("k32");
M("Khi quan sát thấy con vật có 6 chân, cơ thể chia 3 phần, có cánh. Con vật đó thuộc nhóm",["Côn trùng (ngành Chân khớp)","Thân mềm","Giun","Cá"],1);
V("Gặp tổ ong vò vẽ trên cây khi đi thực hành, em nên",["tránh xa, báo thầy cô, không chọc phá","ném đá vào tổ","chụp ảnh thật gần","rung cây"],1);

VL("k33");
M("Vì sao đa dạng sinh học suy giảm gây ảnh hưởng đến con người?",["Vì mất nguồn thực phẩm, thuốc, cân bằng sinh thái bị phá vỡ","Vì con người có thêm tài nguyên","Vì không có ảnh hưởng","Vì khí hậu mát hơn"],1);
V("Vườn quốc gia Cát Tiên, Cúc Phương có vai trò",["bảo tồn đa dạng sinh học, nghiên cứu khoa học, du lịch sinh thái","khai thác gỗ","xây khu công nghiệp","săn bắt thú"],1);
T("Bảo vệ đa dạng sinh học:",["+Không mua bán, sử dụng sản phẩm từ động vật hoang dã quý hiếm.","+Trồng cây gây rừng, bảo vệ môi trường sống của sinh vật.","-Đưa nhiều loài lạ vào tự nhiên không gây hại gì.","+Tuyên truyền để mọi người cùng bảo vệ."],1);

VL("k34");
M("Khi tìm hiểu sinh vật ở ao hồ, mẫu nước nên lấy ở",["gần bờ và gần các cây thủy sinh, nơi có nhiều sinh vật","giữa hồ sâu một mình","bất kì đâu không cần chú ý an toàn","dưới đáy hồ khi lặn"],1);
V("Bài báo cáo tìm hiểu sinh vật của nhóm em cần có thêm phần nào để thể hiện tinh thần bảo vệ thiên nhiên?",["Đề xuất biện pháp bảo vệ các sinh vật đã quan sát","Danh sách sinh vật có thể bắt về nuôi","Giá bán các sinh vật","Không cần thêm gì"],1);

VL("k35");
M("Để biểu diễn lực kéo 30 N theo phương ngang, chiều từ trái sang phải, tỉ xích 1 cm ứng với 10 N thì mũi tên dài",["3 cm, hướng sang phải","30 cm, hướng sang trái","1 cm, hướng lên trên","10 cm, hướng xuống dưới"],1);
S("Mũi tên biểu diễn lực dài 5 cm, tỉ xích 1 cm ứng với 20 N. Độ lớn của lực là bao nhiêu N?","100",1);
T("Biểu diễn lực:",["+Gốc mũi tên là điểm đặt của lực.","+Hướng mũi tên cho biết phương và chiều của lực.","-Mũi tên càng dài thì lực càng nhỏ.","+Cần chọn tỉ xích phù hợp khi biểu diễn lực."],1);

VL("k36");
M("Một lực vừa làm quả bóng bị méo vừa làm quả bóng bay đi là khi",["cầu thủ sút mạnh vào quả bóng","quả bóng nằm yên","quả bóng lăn chậm không ai chạm","bóng để trong tủ"],1);
V("Trong môn kéo co, đội thắng là đội",["tác dụng lực kéo lớn hơn về phía mình","đứng yên không kéo","có ít người hơn","đứng xa sợi dây"],1);
T("Kết quả tác dụng của lực:",["+Hãm phanh làm xe đạp chạy chậm lại.","+Nặn đất sét làm đất sét biến dạng.","-Lực chỉ làm vật chuyển động nhanh hơn.","+Gió mạnh làm cành cây cong đi."],1);

VL("k37");
S("Một quả dưa có trọng lượng 30 N. Khối lượng của quả dưa khoảng bao nhiêu kg?","3",1);
M("Trên Mặt Trăng, lực hút nhỏ hơn Trái Đất khoảng 6 lần. Một người có khối lượng 60 kg khi lên Mặt Trăng thì",["khối lượng vẫn 60 kg, trọng lượng khoảng 100 N","khối lượng còn 10 kg","trọng lượng vẫn 600 N","khối lượng tăng lên"],1);
T("Phân biệt khối lượng và trọng lượng:",["+Khối lượng đo bằng cân, đơn vị kg.","+Trọng lượng đo bằng lực kế, đơn vị N.","-Lên Mặt Trăng, khối lượng của vật giảm đi 6 lần.","+Trọng lượng phụ thuộc vào lực hút nơi đặt vật."],1);

VL("k38");
M("Quả táo nằm yên trên mặt đất. Lực Trái Đất hút quả táo và lực mặt đất đỡ quả táo lần lượt là",["lực không tiếp xúc và lực tiếp xúc","lực tiếp xúc và lực không tiếp xúc","đều là lực tiếp xúc","đều là lực không tiếp xúc"],1);
V("Khi chơi đồ chơi xe ô tô có nam châm, đưa nam châm lại gần thì xe chạy theo mà không chạm vào. Lực tác dụng lên xe là",["lực không tiếp xúc (lực từ)","lực tiếp xúc","lực ma sát","lực đàn hồi"],1);

VL("k39");
S("Lò xo dài 15 cm. Treo vật 50 g thì lò xo dài 16 cm. Muốn lò xo dài 18 cm thì cần treo vật bao nhiêu gam (trong giới hạn đàn hồi)?","150",1);
M("Vì sao không nên treo vật quá nặng vào lực kế?",["Vì vượt quá giới hạn đàn hồi, lò xo bị hỏng, không trở lại hình dạng cũ","Vì lực kế sẽ nhẹ đi","Vì kim chỉ sai màu","Vì vật sẽ rơi"],1);
T("Đo lực bằng lực kế:",["+Cần chọn lực kế có GHĐ lớn hơn lực cần đo.","+Đọc số chỉ khi kim đã đứng yên.","-Có thể đo lực mà không cần hiệu chỉnh vạch 0.","+Lực kế được cầm theo phương của lực cần đo."],1);

VL("k40");
M("Vì sao vận động viên trượt băng có thể lướt nhanh trên mặt băng?",["Vì ma sát giữa giày trượt và mặt băng rất nhỏ","Vì ma sát rất lớn","Vì băng rất nóng","Vì không có trọng lực"],1);
V("Cửa tủ bị kêu cót két khi đóng mở. Cách khắc phục là",["tra dầu mỡ vào bản lề để giảm ma sát","rắc cát vào bản lề","đóng cửa mạnh hơn","dán băng dính"],1);
T("Ma sát trong đời sống:",["+Ma sát nghỉ giữ cho vật đứng yên trên mặt nghiêng.","+Đế giày có khía để tăng ma sát.","-Muốn xe chạy nhanh trên đường trơn, cần giảm ma sát của lốp.","+Ma sát làm nóng các bộ phận máy móc."],1);

VL("k41");
M("Quả bóng được giữ yên trên cao có dạng năng lượng nào?",["Thế năng (hấp dẫn)","Động năng","Quang năng","Âm năng"],1);
V("Vì sao khi chạy bộ lâu, cơ thể nóng lên và đổ mồ hôi?",["Vì năng lượng hóa học từ thức ăn chuyển hóa thành động năng và nhiệt năng","Vì trời mưa","Vì cơ thể lạnh đi","Vì quần áo nóng"],1);
T("Các dạng năng lượng:",["+Gió có động năng làm quay cánh quạt gió.","+Thức ăn chứa năng lượng hóa học.","-Pin mặt trời biến điện năng thành quang năng.","+Loa biến điện năng thành năng lượng âm thanh."],1);

VL("k42");
S("Một bóng đèn tiêu thụ 100 J điện năng, phát ra 20 J năng lượng ánh sáng. Năng lượng hao phí (nhiệt) là bao nhiêu J?","80",1);
M("Khi thả quả bóng rơi, bóng nảy lên thấp dần rồi dừng lại. Năng lượng của bóng",["chuyển dần thành nhiệt năng, âm thanh (không mất đi)","biến mất hoàn toàn","tăng lên","không thay đổi dạng"],1);
T("Sử dụng năng lượng hiệu quả:",["+Thiết bị có hiệu suất cao thì lãng phí năng lượng ít.","+Tận dụng ánh sáng tự nhiên giúp tiết kiệm điện.","-Năng lượng hao phí là năng lượng bị mất hẳn.","+Đi xe đạp thay xe máy giúp tiết kiệm nhiên liệu."],1);

VL("k43");
M("Vì sao người ta thường xây nhà hướng nam ở Việt Nam?",["Vì mùa hè đón gió mát, mùa đông tránh gió lạnh, đón nắng hợp lí","Vì Mặt Trời mọc ở hướng nam","Vì hướng nam không có gió","Vì hướng nam gần biển"],1);
V("Buổi chiều, bóng của cột cờ đổ về hướng nào?",["Hướng đông","Hướng tây","Hướng nam","Hướng bắc"],1);

VL("k44");
M("Vì sao ta luôn chỉ thấy một mặt của Mặt Trăng?",["Vì Mặt Trăng tự quay một vòng đúng bằng thời gian quay quanh Trái Đất","Vì Mặt Trăng không quay","Vì mặt kia luôn tối","Vì Trái Đất che khuất"],1);
V("Ngày mùng 1 Âm lịch thường không nhìn thấy trăng vì",["Mặt Trăng ở giữa Trái Đất và Mặt Trời, phần được chiếu sáng quay về phía Mặt Trời","Mặt Trăng biến mất","trời luôn có mây","Mặt Trăng tắt sáng"],1);
T("Các pha của Mặt Trăng:",["+Trăng tròn xảy ra khoảng ngày 15 Âm lịch.","+Trăng khuyết đầu tháng và cuối tháng có phần sáng ở hai phía khác nhau.","-Mặt Trăng tự thay đổi kích thước theo ngày.","+Một chu kì các pha khoảng 29,5 ngày."],1);

VL("k45");
M("Vì sao Sao Kim là hành tinh sáng nhất trên bầu trời đêm (sau Mặt Trăng)?",["Vì gần Trái Đất và có lớp mây phản xạ mạnh ánh sáng Mặt Trời","Vì Sao Kim tự phát sáng","Vì Sao Kim to nhất","Vì Sao Kim là ngôi sao"],1);
V("Ánh sáng từ Mặt Trời đến Trái Đất mất khoảng 8 phút. Điều đó cho thấy",["khoảng cách từ Trái Đất đến Mặt Trời rất xa","Mặt Trời ở rất gần","ánh sáng đi rất chậm","Mặt Trời là hành tinh"],1);
T("Về hệ Mặt Trời và Ngân Hà:",["+Hành tinh vòng ngoài có kích thước lớn hơn hành tinh vòng trong.","+Ngân Hà có dạng đĩa xoắn ốc.","-Mặt Trời là ngôi sao lớn nhất vũ trụ.","+Mặt Trời là một trong hàng trăm tỉ ngôi sao của Ngân Hà."],1);

/* ---- TIN HỌC ---- */
VL("t6");
M("Điểm khác nhau giữa Internet và WWW là",["Internet là mạng kết nối máy tính; WWW là một dịch vụ (các trang web) chạy trên Internet","Hai khái niệm hoàn toàn giống nhau","WWW lớn hơn Internet","Internet là một trang web"],1);
V("Em gõ sai một kí tự trong địa chỉ trang web và vào một trang lạ đòi đăng nhập. Em nên",["thoát ra, kiểm tra lại địa chỉ, không nhập thông tin","nhập mật khẩu thử","tải tệp về","chia sẻ trang cho bạn"],1);
T("Về trang web và trình duyệt:",["+Có thể mở nhiều trang web trên các thẻ (tab) khác nhau.","+Địa chỉ bắt đầu bằng https thường được bảo mật hơn.","-Một trang web chỉ chứa được chữ.","+Nút quay lại giúp trở về trang đã xem trước đó."],1);

VL("t7");
