VL("g5");
M("Phân biệt tự lập và tự cao: tự lập là",["tự làm, tự chịu trách nhiệm nhưng vẫn biết học hỏi, nhờ giúp đỡ khi cần","không bao giờ nhờ ai, coi thường người khác","làm theo ý mình bất chấp","từ chối mọi lời khuyên"],1);
V("Bạn K học lớp 6 nhưng mọi việc cá nhân đều để bố mẹ làm. Kế hoạch rèn tự lập phù hợp cho K là",["tự dậy đúng giờ, tự soạn sách vở, tự gấp quần áo, làm việc nhà vừa sức","tiếp tục để bố mẹ làm","thuê người làm hộ","bỏ học"],1);

VL("g6");
M("Bạn H nói: “Mình chẳng có điểm mạnh nào cả.” Lời khuyên phù hợp là",["hãy tự quan sát, hỏi người thân, thầy cô để nhận ra điểm mạnh của mình","đồng ý với H","so sánh H với bạn giỏi nhất lớp","bảo H đừng cố gắng nữa"],1);
V("Sau bài kiểm tra điểm thấp, cách tự nhận thức đúng là",["xem lại bài, tìm lỗi sai, lập kế hoạch khắc phục","đổ lỗi cho đề khó","nghĩ mình kém cỏi, bỏ cuộc","giấu bài kiểm tra"],1);

VL("g7");
M("Khi bị kẹt trong thang máy, việc làm đúng là",["bình tĩnh, bấm chuông báo động, gọi điện cứu hộ, không cố cạy cửa","cố cạy cửa nhảy ra","nhảy mạnh trong thang","la hét và đập phá"],1);
V("Em thấy bạn bị đuối nước ở hồ, em không biết bơi. Em nên",["hô hoán người lớn, gọi cứu hộ, ném phao/vật nổi cho bạn","nhảy xuống cứu ngay","bỏ đi","đứng xem"],1);
T("Ứng phó tình huống nguy hiểm:",["+Khi bão, cần ở trong nhà kiên cố, tránh xa cột điện, cây lớn.","+Khi có cháy, bò thấp và dùng khăn ướt che mũi miệng.","-Khi bị người lạ bám theo, nên đi vào ngõ vắng để trốn.","+Ghi nhớ số điện thoại khẩn cấp 113, 114, 115."],1);

VL("g8");
M("Bạn P không dám tiêu tiền cho cả việc mua sách cần thiết. Hành vi này là",["keo kiệt, không phải tiết kiệm","tiết kiệm đúng mức","lãng phí","hào phóng"],1);
S("Mỗi ngày em tiết kiệm 5 000 đồng tiền ăn sáng thừa. Sau 30 ngày em có bao nhiêu đồng?","150000",1);
T("Tiết kiệm đúng cách:",["+Lập kế hoạch chi tiêu giúp tiết kiệm hiệu quả.","+Tận dụng giấy một mặt để làm nháp.","-Tiết kiệm là không tiêu tiền vào việc gì.","+Tắt vòi nước khi đánh răng là tiết kiệm nước."],1);

VL("g9");
M("Bạn A sinh ra ở nước ngoài, có cha mẹ đều là công dân Việt Nam. Theo pháp luật, A",["có quốc tịch Việt Nam","không có quốc tịch","là người nước ngoài","chỉ có quốc tịch nước nơi sinh"],1);
V("Là công dân nhỏ tuổi, em thể hiện trách nhiệm với đất nước bằng cách",["học tập tốt, chấp hành pháp luật, giữ gìn văn hóa dân tộc","không quan tâm việc chung","vi phạm luật giao thông","phá hoại của công"],1);

VL("g10");
M("Quyền và nghĩa vụ của công dân có mối quan hệ",["gắn bó với nhau, công dân được hưởng quyền đồng thời phải làm nghĩa vụ","không liên quan","chỉ có quyền","chỉ có nghĩa vụ"],1);
V("Bạn em đi xe đạp dàn hàng ba trên đường. Em nhắc bạn vì",["đó là vi phạm luật giao thông, không thực hiện nghĩa vụ công dân, gây nguy hiểm","đi như vậy rất an toàn","không ai quan tâm","luật không áp dụng cho học sinh"],1);
T("Quyền và nghĩa vụ cơ bản:",["+Công dân có quyền tự do ngôn luận theo quy định pháp luật.","+Bảo vệ Tổ quốc là nghĩa vụ thiêng liêng.","-Công dân có quyền xâm phạm tài sản của người khác.","+Mọi công dân bình đẳng về quyền và nghĩa vụ."],1);

VL("g11");
M("Hành vi nào vi phạm quyền trẻ em?",["Bắt trẻ em nghỉ học đi làm thuê","Cho trẻ đi tiêm phòng","Lắng nghe ý kiến của trẻ","Cho trẻ vui chơi"],1);
V("Bố mẹ hỏi ý kiến em khi chọn trường cấp 2. Điều đó thể hiện quyền",["được tham gia, bày tỏ ý kiến","sống còn","được bảo vệ","được chăm sóc sức khỏe"],1);
T("Các nhóm quyền trẻ em:",["+Được khai sinh, có quốc tịch thuộc nhóm quyền sống còn.","+Được bảo vệ khỏi bị bóc lột sức lao động thuộc nhóm quyền bảo vệ.","-Quyền vui chơi thuộc nhóm quyền sống còn.","+Được học tập thuộc nhóm quyền phát triển."],1);

VL("g12");
M("Khi phát hiện trẻ em bị bạo hành, trách nhiệm của mọi người là",["báo ngay cho cơ quan chức năng hoặc tổng đài 111","im lặng vì không phải việc của mình","quay video đăng mạng","đánh lại người bạo hành"],1);
V("Trường tổ chức buổi học kĩ năng phòng chống xâm hại. Đây là việc thực hiện trách nhiệm của",["nhà trường trong bảo vệ trẻ em","chỉ gia đình","chỉ công an","không ai"],1);
T("Bổn phận và trách nhiệm:",["+Trẻ em có bổn phận học tập, rèn luyện đạo đức.","+Gia đình tạo điều kiện để trẻ được học tập, vui chơi.","-Chỉ nhà nước có trách nhiệm thực hiện quyền trẻ em.","+Trẻ em cần biết tự bảo vệ và tìm người tin cậy khi gặp nguy hiểm."],1);
